SELECT
    p.*,
    c.category_name AS categoryName
FROM t_product p
LEFT JOIN t_product_category c ON c.category_id = p.category_id


        AND p.deleted_flag = #{queryForm.deletedFlag}


        AND p.category_id = #{queryForm.categoryId}


        AND (INSTR(p.product_name, #{queryForm.searchWord}) OR INSTR(p.product_no, #{queryForm.searchWord}))


        AND p.product_type = #{queryForm.productType}


        AND p.status = #{queryForm.status}



    ORDER BY p.product_id DESC

